6435:  /// The code from the link — User.referralCode or ReferralPartner.code.

// AffiliatePayout), which pays a ONE-TIME wallet bonus to a customer who refers a
// friend. This program is for agencies / content creators (KOLs) who bring on
// customers and then earn a LIFETIME percentage on EVERY qualifying charge that
// customer ever makes — initial orders AND renewals, across every product. The
// partner stays permanently attached to the customer.
//
// All three models are additive and never alter an existing table.

/// An agency or content creator (KOL) partner. `code` is the referral code they
/// hand to prospective clients; a signup/order carrying it attaches that customer
/// to this partner for life (see PartnerCustomer). `commissionRatePct` is the
/// lifetime rate; it is FROZEN onto each PartnerCommission row at accrual, so a
/// later rate change never rewrites already-earned commission.
model ReferralPartner {
  id                String              @id @default(cuid())
  // Optional login account the partner uses to view their portal at
  // /dashboard/partner. A partner may exist purely as an admin-managed record
  // (no login) until they self-serve. SetNull so deleting the user keeps history.
  userId            String?             @unique
  user              User?               @relation("PartnerAccount", fields: [userId], references: [id], onDelete: SetNull)
  name              String
  contactEmail      String?
  code              String              @unique
  // Lifetime commission rate (percent of the NET, pre-tax charge) earned on every
  // qualifying charge by every attached customer.
  commissionRatePct Float               @default(20)
  status            String              @default("ACTIVE") // ACTIVE | PAUSED
  notes             String?
  createdAt         DateTime            @default(now())
  customers         PartnerCustomer[]
  commissions       PartnerCommission[]
  payouts           PartnerPayout[]
  invites           PartnerInvite[]
  payoutProfile     PartnerPayoutProfile?
  /// What KIND of partner this is: agency | kol | community | developer |
  /// reseller. Display only — the commission rate is `commissionRatePct` and
  /// is not derived from this. Null on partners linked before the field existed.
  type              String?
}

/// The durable link binding a referred customer to their referring partner for the
/// life of the account. `customerId` is UNIQUE: a customer is attached to exactly
/// ONE partner, permanently — the "lifetime attribution" guarantee.
model PartnerCustomer {
  id         String          @id @default(cuid())
  partnerId  String
  partner    ReferralPartner @relation(fields: [partnerId], references: [id], onDelete: Cascade)
  customerId String          @unique
  customer   User            @relation("PartnerAttachment", fields: [customerId], references: [id], onDelete: Cascade)
  attachedAt DateTime        @default(now())
  createdAt  DateTime        @default(now())
  // CREATOR PARTNER PROGRAM pricing (2026-09-26): null until this customer's
  // first-ever discounted (non-domain) purchase completes while attached — that
  // purchase is sold at PARTNER_FIRST_PURCHASE_PCT (50%) off, and every purchase
  // AFTER this timestamp is stamped sells at PARTNER_RECURRING_PCT (10%) off,
  // forever. See lib/partner-discount.ts. Claimed ATOMICALLY (an `updateMany`
  // guarded on this column being null, inside the same charge transaction that
  // debits the wallet / confirms the card charge) so two concurrent "first"
  // orders for the same customer can never both be sold at 50%.
  firstPurchaseDiscountUsedAt DateTime?

  @@index([partnerId])
}

/// One commission entry per qualifying charge. `invoiceId` is UNIQUE — this is the
/// idempotency guard: at most one commission row can ever exist per invoice, so a
  ORDER
}

/// Which product family a coupon may be redeemed against at checkout.
enum CouponServiceKind {
  ANY
  VPS
  GAME
}

model Coupon {
  id             String             @id @default(cuid())
  code           String             @unique
  kind           CouponKind
  value          Int
  scope          CouponScope        @default(ANY)
  // Which product family this coupon may be used on at checkout. ANY = no
  // restriction; VPS / GAME limit it to that kind of order.
  serviceKind    CouponServiceKind  @default(ANY)
  // Restrict to ONE specific plan by slug (e.g. "starter"). Null = any plan
  // within `serviceKind`. This is how "one free month on the Starter VPS" is
  // locked to Starter and cannot be spent on a bigger plan.
  planSlug       String?
  // Cap how many months of the term the coupon may discount. 1 = one month only,
  // so a percentage/free coupon cannot be stretched across a 12-month order to
  // give a year free. Null = the whole term.
  maxTermMonths  Int?
  firstTimeOnly  Boolean            @default(false)
  // Distinct from firstTimeOnly, which (see lib/coupon-redemption.ts) means
  // "has never had ANY non-free server, ever" — that would reject a churned
  // customer this kind of acquisition/win-back promo should welcome back.
  // This instead means "has no CURRENTLY active non-free server right now" —
  // checked the same everywhere firstTimeOnly is (lib/coupon-redemption.ts,
  // lib/order.ts's claimOrderCoupon + orderCouponClaimable).
  excludeActiveCustomers Boolean    @default(false)
  minAmountCents Int?
  maxRedemptions Int?
  timesRedeemed  Int                @default(0)
  expiresAt      DateTime?
  active         Boolean            @default(true)
  note           String?
  createdAt      DateTime           @default(now())
  redemptions    CouponRedemption[]
  // A trial promo's SHORT first period, in days — e.g. 7. When set, order
  // creation (lib/order.ts, lib/game-order.ts) sets the new Server's
  // `expiresAt` to now + this many days INSTEAD OF the plan's normal
  // (month-granular) term length, so the very next renewal lands on day N —
  // not a month later — and charges at `Server.grandfatheredRenewalCents`
  // (already the plan's real regular price by default), which is the whole
  // "reverts to standard price after the trial" mechanic. Null for every
  // ordinary coupon; only a real trial promo sets it.
  trialDays      Int?
}

model CouponRedemption {
  id               String    @id @default(cuid())
  couponId         String
  coupon           Coupon    @relation(fields: [couponId], references: [id], onDelete: Cascade)
  userId           String
  user             User      @relation(fields: [userId], references: [id], onDelete: Cascade)
  amountCents      Int       @default(0)
  context          String    @default("")
  // Hashed claimant IP (sha256 of ip+salt) — enforces "once per person" beyond
  // one-per-account, so a coupon can't be farmed with throwaway signups. Null on
  // legacy rows / when the IP was unavailable; Postgres treats NULLs as distinct
  // so the unique below never collides on them.
  ipHash           String?
  // Reservation lifecycle — the fix for the card/Stripe (up-front-settlement) race,
  // mirroring PromoRedemption below. UNLIKE the promo, a coupon carries a CONFIGURABLE
  // cap (`Coupon.timesRedeemed` / `maxRedemptions`) on top of the two unique slots, so
  // the reserve/release helpers (lib/coupon-redemption.ts) increment/decrement that
  // counter in lockstep with a hold's creation/deletion.
  //   CONSUMED — a GRANTED redemption. The wallet-atomic path (lib/order.ts
  //              claimOrderCoupon) inserts this directly, so the default keeps that
  //              insert-and-grant flow behaving exactly as before.
  //   RESERVED — a HOLD taken at checkout-CREATE time, BEFORE the card is charged, so a
  //              second concurrent card checkout can't also pass the per-person/global
  //              caps and walk away discounted. Confirmed to CONSUMED at fulfilment, or
  //              released (row deleted + timesRedeemed decremented) on expiry/sweep.
  // Both states occupy the same (couponId,userId)/(couponId,ipHash) unique slots, so a
