export type PartnerFunnel = {
  /** Rows in ReferralClick for this partner's code — real link clicks recorded by
   *  app/partner/[code]/route.ts (and app/r/[code]/route.ts for the legacy path). */
  clicked: number;
  /** PartnerCustomer rows — real, permanently-attached signups. */
  signedUp: number;
  /** Distinct customers with at least one PartnerCommission row — their first paid purchase. */
  converted: number;
};

/**
 * Real click → signup → conversion funnel for one partner, shown on both the
 * partner's own dashboard and the admin detail page. Every number here is a real
 * count off a real table — no estimates, no placeholders (see this codebase's own
 * "never fabricate" rule).
 */
export async function partnerFunnel(partnerId: string, code: string): Promise<PartnerFunnel> {
  const [clicked, signedUp, convertedRows] = await Promise.all([
    db.referralClick.count({ where: { code } }),
    db.partnerCustomer.count({ where: { partnerId } }),
    db.partnerCommission.groupBy({ by: ["customerId"], where: { partnerId } }),
  ]);
  return { clicked, signedUp, converted: convertedRows.length };
}

/**
 * Attach a customer to the partner whose `code` matches, for life. No-op if the
 * code doesn't map to an ACTIVE partner, or the customer is already attached to a
 * partner (attachment is permanent and single — the unique `customerId` also hard-
 * enforces this). Best-effort: returns whether an attachment was made. Intended to
 * be called from the registration flow when a `?ref=` code is a partner code.
 */
export async function attachCustomerToPartnerByCode(
  customerId: string,
  rawCode: string | null | undefined
): Promise<boolean> {
  // Partner codes are stored upper-cased (see lib/actions-partner.ts normalizeCode).
  const code = (rawCode ?? "").trim().toUpperCase();
  if (!code) return false;
  try {
    const partner = await db.referralPartner.findUnique({ where: { code } });
    if (!partner || partner.status !== "ACTIVE") return false;
    // A partner cannot self-attach (would earn commission on their own spend).
    if (partner.userId && partner.userId === customerId) return false;
    const existing = await db.partnerCustomer.findUnique({ where: { customerId } });
    if (existing) return false;
    await db.partnerCustomer.create({ data: { partnerId: partner.id, customerId } });
    // Best-effort: mark the click that most likely led to this signup as
    // converted, so the real click funnel (partnerFunnel above) can show a
    // clicked -> signed up rate. There's no session id carried from click to
    // registration (the cookie only carries the code — see app/partner/[code]/
    // route.ts), so this attributes to the most recent NOT-YET-CONVERTED click
    // for this exact code — a reasonable best match, never load-bearing for
    // billing (only PartnerCustomer/PartnerCommission are, and both are already
    // committed above/elsewhere).
    try {
      const click = await db.referralClick.findFirst({
        where: { code, convertedUserId: null },
        orderBy: { createdAt: "desc" },
      });
      if (click) {
        await db.referralClick.update({ where: { id: click.id }, data: { convertedUserId: customerId } });
      }
    } catch {
      /* analytics-only, never blocks the real attachment above */
    }
    return true;
  } catch (e) {
    // Unique race (two concurrent attaches) or transient error — never fatal to
    // the caller (registration/order must still succeed).
    if ((e as Prisma.PrismaClientKnownRequestError)?.code === "P2002") return false;
    console.error("[partner-commission] attach-by-code failed for", customerId, e);
    return false;
  }
}
