/** Show enough of a value to recognise it, never enough to reuse it. */
function tail(v: string, n = 4): string {
  return v.length <= n ? v : `•••• ${v.slice(-n)}`;
}
function maskEmail(e: string): string {
  const [user, domain] = e.split("@");
  if (!domain) return tail(e);
  return `${user.slice(0, 1)}•••@${domain}`;
}

