// Mask a customer's email for display to a THIRD PARTY (a Creator Partner).
//
// Pure and DB-free so it is unit-tested directly (test/creator-code.test.ts).
//
// Why: a customer who signed up through a creator's code/link agreed to
// Nxeon's terms, not to having their address shown to that creator. The
// partner dashboard (app/dashboard/partner/page.tsx, lib/partner-analytics.ts)
// still needs to tell rows apart, so it gets a recognisable-but-unusable form:
//
//   john.doe@gmail.com      -> j•••@g•••.com
//   a@example.co.uk         -> a•••@e•••.uk
//
// Masking happens SERVER-SIDE, before the value is serialised into the page —
// the raw address never reaches the partner's browser. Admin views keep reading
// the real `User.email` directly and are unaffected.

const DOTS = "•••";

export function maskEmail(raw: string | null | undefined): string {
  const email = (raw ?? "").trim();
  const at = email.lastIndexOf("@");
  if (at <= 0 || at === email.length - 1) return DOTS;
  const local = email.slice(0, at);
  const domain = email.slice(at + 1);
  const labels = domain.split(".").filter(Boolean);
  const first = [...local][0] ?? "";
  if (labels.length < 2) return `${first}${DOTS}@${DOTS}`;
  const host = [...labels[0]][0] ?? "";
  const tld = labels[labels.length - 1];
  return `${first}${DOTS}@${host}${DOTS}.${tld}`;
}

