    if (!partner || partner.status !== "ACTIVE") return false;
    // A partner cannot self-attach (would earn commission on their own spend).
    if (partner.userId && partner.userId === customerId) return false;
    const existing = await db.partnerCustomer.findUnique({ where: { customerId } });
    if (existing) return false;
    await db.partnerCustomer.create({ data: { partnerId: partner.id, customerId } });
    // Best-effort: mark the click that most likely led to this signup as
    // converted, so the real click funnel (partnerFunnel above) can show a
    // clicked -> signed up rate. There's no session id carried from click to
    // registration (the cookie only carries the code — see app/partner/[code]/
    // route.ts), so this attributes to the most recent NOT-YET-CONVERTED click
    // for this exact code — a reasonable best match, never load-bearing for
    // billing (only PartnerCustomer/PartnerCommission are, and both are already
    // committed above/elsewhere).
    if (opts.markClick !== false) try {
      const click = await db.referralClick.findFirst({
        where: { code, convertedUserId: null },
        orderBy: { createdAt: "desc" },
      });
      if (click) {
        await db.referralClick.update({ where: { id: click.id }, data: { convertedUserId: customerId } });
      }
    } catch {
      /* analytics-only, never blocks the real attachment above */
    }
    return true;
  } catch (e) {
    // Unique race (two concurrent attaches) or transient error — never fatal to
    // the caller (registration/order must still succeed).
    if ((e as Prisma.PrismaClientKnownRequestError)?.code === "P2002") return false;
    console.error("[partner-commission] attach-by-code failed for", customerId, e);
    return false;
  }
}

