// CREATOR PARTNER PROGRAM — a creator code TYPED by the customer (2026-09-28).
//
// Until now a partner code only worked through the link /partner/<CODE>
// (app/partner/[code]/route.ts -> `nxeon_ref` cookie -> register() attaches the
// customer). A viewer told "use my code SAM" who simply TYPED it anywhere got
// nothing. This module is the one set of rules for the two places a code can now
// be typed:
//
//   1. /register's optional "Creator code" field -> lib/actions.ts register(),
//      which attaches through the SAME attachCustomerToPartnerByCode the cookie
//      path uses (a new account can't have a partner or a purchase yet, so only
//      "is this a real, ACTIVE partner code" needs checking — `signupCreatorCode`).
//
//   2. The deploy wizard's EXISTING promo-code box (components/nx/DeployView.tsx)
//      -> lib/actions-creator-code.ts. On an existing account the code attaches
//      the partner only when ALL of these hold (`creatorCodeVerdict`):
//        - it is a real partner code and NOT also a Coupon code (a Coupon with the
//          same code keeps the box's existing coupon meaning — nothing changes for
//          any coupon that works today);
//        - it is not the account's OWN partner code (no self-referral — the same
//          rule attachCustomerToPartnerByCode already enforces);
//        - the account is not already linked to a partner (attachment is permanent
//          and single — PartnerCustomer.customerId is UNIQUE);
//        - the partner is ACTIVE (a PAUSED partner gets no new customers, the same
//          gate the cookie path applies);
//        - the account has made NO paid purchase yet (`hasMadePaidPurchase`) —
//          "creator codes apply to a first purchase". Without this, an existing
//          customer could type any creator's code and pick up 50% off their NEXT
//          order plus a lifetime 10%, and the creator would earn commission on a
//          customer they never brought.
//
// Once attached, NOTHING new prices anything: the existing partner-discount path
// (lib/partner-pricing.ts partnerDiscountForNewOrder, read by orderQuote /
// gameOrderQuote and by the charge itself) sees the PartnerCustomer row and the
// quote and the charge pick up the discount together — displayed === charged is
// preserved by construction, not by a second formula.

import type { Prisma } from "@prisma/client";
import { db } from "./db";
import { NON_COMMISSIONABLE_DESCRIPTIONS } from "./partner-commission";

/** Same canonical form every partner-code reader already uses: trimmed, UPPERCASE. */
export function normalizeCreatorCode(raw: string | null | undefined): string {
  return String(raw ?? "").trim().toUpperCase().slice(0, 32);
}

/** The character set app/partner/[code]/route.ts accepts for a code. */
export function looksLikeCreatorCode(code: string): boolean {
  return code.length >= 2 && /^[A-Z0-9_-]+$/.test(code);
}

export type CreatorCodeRefusal = "inactive" | "own" | "linked" | "purchased";

export type CreatorCodeVerdict =
  /** Not a creator code (unknown, or a Coupon owns this code) — the promo box
   *  falls back to its normal coupon handling. */
  | { kind: "none" }
  | { kind: "eligible"; code: string; partnerName: string }
  /** Already linked to THIS creator — nothing to do, the discount already applies. */
  | { kind: "linked-same"; code: string; partnerName: string }
  | { kind: "refused"; code: string; reason: CreatorCodeRefusal; message: string };

export const CREATOR_CODE_MESSAGES: Record<CreatorCodeRefusal, string> = {
  own: "That's your own creator code — it can't be used on your own account.",
  linked: "This account is already linked to a creator.",
  inactive: "This creator code isn't active right now.",
  purchased: "Creator codes apply to a first purchase — this account has already bought something.",
};

/**
 * Pure decision (unit-tested in test/creator-code.test.ts). The order of the
 * checks decides which message a customer sees when more than one applies; the
 * most specific, most actionable one wins.
 */
export function creatorCodeVerdict(facts: {
  code: string;
  couponExists: boolean;
  partner: { id: string; name: string; status: string; userId: string | null } | null;
  customerId: string;
  attachedPartnerId: string | null;
  hasPaidPurchase: boolean;
}): CreatorCodeVerdict {
  const { code, partner } = facts;
  if (!partner || facts.couponExists) return { kind: "none" };
  const refuse = (reason: CreatorCodeRefusal): CreatorCodeVerdict =>
    ({ kind: "refused", code, reason, message: CREATOR_CODE_MESSAGES[reason] });
  if (partner.userId && partner.userId === facts.customerId) return refuse("own");
  if (facts.attachedPartnerId) {
    return facts.attachedPartnerId === partner.id
      ? { kind: "linked-same", code, partnerName: partner.name }
      : refuse("linked");
  }
  if (partner.status !== "ACTIVE") return refuse("inactive");
  if (facts.hasPaidPurchase) return refuse("purchased");
  return { kind: "eligible", code, partnerName: partner.name };
}

/**
 * Has this account bought anything? A PAID (or since REFUNDED — a refund must not
 * reopen the first-purchase window) invoice with a positive total that is not a
 * wallet top-up, the same "is this a real sale" classifier commission accrual uses
 * (lib/partner-commission.ts isCommissionableInvoice) — or any non-free server row.
 * Covers every product (VPS, game, hosting, email, domains, add-ons) because every
 * one of them issues an Invoice.
 */
export async function hasMadePaidPurchase(
  userId: string,
  client: Prisma.TransactionClient | typeof db = db,
): Promise<boolean> {
  const [invoices, servers] = await Promise.all([
    client.invoice.count({
      where: {
        userId,
        status: { in: ["PAID", "REFUNDED"] },
        amountCents: { gt: 0 },
        description: { notIn: [...NON_COMMISSIONABLE_DESCRIPTIONS] },
      },
    }),
    client.server.count({ where: { userId, isFree: false } }),
  ]);
  return invoices > 0 || servers > 0;
}

async function gatherFacts(client: Prisma.TransactionClient | typeof db, userId: string, code: string) {
  const [coupon, partner, attachment, hasPaidPurchase] = await Promise.all([
    client.coupon.findUnique({ where: { code }, select: { id: true } }),
    client.referralPartner.findUnique({
      where: { code },
      select: { id: true, name: true, status: true, userId: true },
    }),
    client.partnerCustomer.findUnique({ where: { customerId: userId }, select: { partnerId: true } }),
    hasMadePaidPurchase(userId, client),
  ]);
  return {
    code,
    couponExists: !!coupon,
    partner,
    customerId: userId,
    attachedPartnerId: attachment?.partnerId ?? null,
    hasPaidPurchase,
  };
}

/** Read-only: what would typing this code into the promo box do for this account? */
export async function resolveCreatorCode(userId: string, rawCode: string): Promise<CreatorCodeVerdict> {
  const code = normalizeCreatorCode(rawCode);
  if (!looksLikeCreatorCode(code)) return { kind: "none" };
  return creatorCodeVerdict(await gatherFacts(db, userId, code));
}

/**
 * Attach the account to the creator whose code this is, re-running every rule
 * inside one transaction. Returns the verdict that applied: `eligible` means the
 * attachment was made by THIS call. A concurrent attach (the UNIQUE customerId)
 * resolves to `linked-same`/`refused: linked` on a re-read, never a crash.
 */
export async function attachCreatorCode(userId: string, rawCode: string): Promise<CreatorCodeVerdict> {
  const code = normalizeCreatorCode(rawCode);
  if (!looksLikeCreatorCode(code)) return { kind: "none" };
  try {
    return await db.$transaction(async (tx) => {
      const verdict = creatorCodeVerdict(await gatherFacts(tx, userId, code));
      if (verdict.kind !== "eligible") return verdict;
      const partner = await tx.referralPartner.findUniqueOrThrow({ where: { code }, select: { id: true } });
      await tx.partnerCustomer.create({ data: { partnerId: partner.id, customerId: userId } });
      return verdict;
    });
  } catch (e) {
    if ((e as Prisma.PrismaClientKnownRequestError)?.code === "P2002") {
      return resolveCreatorCode(userId, code);
    }
    throw e;
  }
}

/**
 * Register-page check: a brand-new account has no partner and no purchase, so the
 * only question is whether the typed code is a real, ACTIVE partner code. The
 * attachment itself then goes through attachCustomerToPartnerByCode, exactly like
 * the cookie path.
 */
export async function signupCreatorCode(
  rawCode: string,
): Promise<{ ok: true; code: string; partnerName: string } | { ok: false; error: string }> {
  const code = normalizeCreatorCode(rawCode);
  const invalid = "That creator code isn't valid. Check the spelling, or clear the field to sign up without one.";
  if (!looksLikeCreatorCode(code)) return { ok: false, error: invalid };
  const partner = await db.referralPartner.findUnique({ where: { code }, select: { name: true, status: true } });
  if (!partner) return { ok: false, error: invalid };
  if (partner.status !== "ACTIVE") return { ok: false, error: CREATOR_CODE_MESSAGES.inactive };
  return { ok: true, code, partnerName: partner.name };
}

