  const code = normalizeCreatorCode(rawCode);
  const invalid = "That creator code isn't valid. Check the spelling, or clear the field to sign up without one.";
  if (!looksLikeCreatorCode(code)) return { ok: false, error: invalid };
  const partner = await db.referralPartner.findUnique({ where: { code }, select: { name: true, status: true } });
