// Creator codes typed into the deploy wizard's EXISTING promo-code box.
// All rules live in lib/creator-code.ts; this module is only the network edge:
// signed-in customer required, rate-limited per account, and the mutating call
// refused while an admin is impersonating (a permanent attribution that changes
// what the customer pays is the customer's decision, same as a spend).
//
// Two exports, both requireUser()-gated:
//   - checkCreatorCode: READ-ONLY. What would this code do for this account?
//   - applyCreatorCode: attaches the account to the creator (permanent).
// Kept out of lib/nx/quote.ts on purpose — that module's contract is "exactly one
// read-only export".

import { headers } from "next/headers";
import { requireUser, impersonating } from "./auth";
import { checkRateLimit, clientIp } from "./rate-limit";
import { recordAudit } from "./audit";
import { attachCreatorCode, resolveCreatorCode, type CreatorCodeVerdict } from "./creator-code";

export type CreatorCodeCheck =
  | { kind: "none" }
  | { kind: "eligible"; code: string; partnerName: string }
  | { kind: "linked-same"; code: string; partnerName: string }
  | { kind: "refused"; code: string; message: string };

function toCheck(v: CreatorCodeVerdict): CreatorCodeCheck {
  if (v.kind === "refused") return { kind: "refused", code: v.code, message: v.message };
  return v;
}

export async function checkCreatorCode(rawCode: string): Promise<CreatorCodeCheck> {
  const user = await requireUser();
  const code = String(rawCode ?? "").slice(0, 64);
  // Debounced per keystroke-pause in the wizard, so a generous allowance for a
  // real customer, but enough of a ceiling that the box is not a code-enumeration
  // oracle (partner codes are public by design; this only bounds the scraping).
  const rl = checkRateLimit(`creator-code-check:${user.id}`, { max: 40, windowMs: 10 * 60 * 1000 });
  if (!rl.ok) return { kind: "refused", code: code.toUpperCase(), message: `Too many code checks. Try again in ${rl.retryAfterSec}s.` };
  try {
    return toCheck(await resolveCreatorCode(user.id, code));
  } catch (e) {
    console.error("[creator-code] check failed for", user.id, e);
    // Unknown -> behave as "not a creator code" so the coupon path still answers.
    return { kind: "none" };
  }
}

export async function applyCreatorCode(
  rawCode: string,
): Promise<{ ok: true; partnerName: string } | { ok: false; error: string }> {
  const user = await requireUser();
  if (await impersonating()) {
    return { ok: false, error: "This action is disabled while impersonating a customer. Stop impersonating to continue." };
  }
  const ip = clientIp(await headers());
  const rl = checkRateLimit(`creator-code-apply:${user.id}:${ip}`, { max: 10, windowMs: 15 * 60 * 1000 });
  if (!rl.ok) return { ok: false, error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
  let verdict: CreatorCodeVerdict;
  try {
    verdict = await attachCreatorCode(user.id, String(rawCode ?? "").slice(0, 64));
  } catch (e) {
    console.error("[creator-code] attach failed for", user.id, e);
    return { ok: false, error: "Couldn't apply that code. Try again." };
  }
  switch (verdict.kind) {
    case "eligible":
      await recordAudit(user.id, "partner.customer_attached", `code=${verdict.code} via=checkout-code`);
      return { ok: true, partnerName: verdict.partnerName };
    case "linked-same":
      return { ok: true, partnerName: verdict.partnerName };
    case "refused":
      return { ok: false, error: verdict.message };
    default:
      return { ok: false, error: "That code isn’t valid." };
  }
}

