import { test } from "node:test";
import assert from "node:assert/strict";
import { creatorCodeVerdict, normalizeCreatorCode, looksLikeCreatorCode, CREATOR_CODE_MESSAGES } from "../lib/creator-code.ts";
import { maskEmail } from "../lib/mask-email.ts";
import {
  PARTNER_PAYOUT_POLICY,
  partnerPayoutMinimumLabel,
  partnerPayoutMethodsList,
  partnerPayoutPolicyShort,
  partnerPayoutPolicyFull,
} from "../lib/partner-payout.ts";

/**
 * Creator codes typed into /register or the deploy wizard's promo box
 * (lib/creator-code.ts), partner-facing email masking (lib/mask-email.ts) and the
 * stated payout policy (lib/partner-payout.ts). Pure functions, no DB.
 */

const partner = { id: "p1", name: "Sam's Channel", status: "ACTIVE", userId: "creator-user" };
const base = {
  code: "SAM",
  couponExists: false,
  partner,
  customerId: "cust-1",
  attachedPartnerId: null as string | null,
  hasPaidPurchase: false,
};

test("codes are case-insensitive and trimmed", () => {
  assert.equal(normalizeCreatorCode("  sam "), "SAM");
  assert.equal(normalizeCreatorCode("SaM"), "SAM");
  assert.ok(looksLikeCreatorCode("SAM"));
  assert.ok(!looksLikeCreatorCode("S"));
  assert.ok(!looksLikeCreatorCode("SAM 10"));
  assert.ok(!looksLikeCreatorCode("S@M"));
});

test("fresh account with no purchase: eligible", () => {
  assert.deepEqual(creatorCodeVerdict(base), { kind: "eligible", code: "SAM", partnerName: "Sam's Channel" });
});

test("unknown code, or a code a Coupon also owns: not a creator code (coupon path unchanged)", () => {
  assert.deepEqual(creatorCodeVerdict({ ...base, partner: null }), { kind: "none" });
  assert.deepEqual(creatorCodeVerdict({ ...base, couponExists: true }), { kind: "none" });
});

test("no self-referral: a creator can't use their own code", () => {
  const v = creatorCodeVerdict({ ...base, customerId: "creator-user" });
  assert.equal(v.kind, "refused");
  assert.equal(v.kind === "refused" && v.reason, "own");
});

test("already linked to a different creator: refused with the plain message", () => {
  const v = creatorCodeVerdict({ ...base, attachedPartnerId: "someone-else" });
  assert.equal(v.kind === "refused" && v.message, CREATOR_CODE_MESSAGES.linked);
  assert.equal(CREATOR_CODE_MESSAGES.linked, "This account is already linked to a creator.");
});

test("already linked to THIS creator: linked-same, nothing to do", () => {
  assert.equal(creatorCodeVerdict({ ...base, attachedPartnerId: "p1" }).kind, "linked-same");
});

test("an account that has bought something can't be attached", () => {
  const v = creatorCodeVerdict({ ...base, hasPaidPurchase: true });
  assert.equal(v.kind === "refused" && v.reason, "purchased");
  assert.match(CREATOR_CODE_MESSAGES.purchased, /first purchase/);
});

test("a paused creator takes no new customers", () => {
  const v = creatorCodeVerdict({ ...base, partner: { ...partner, status: "PAUSED" } });
  assert.equal(v.kind === "refused" && v.reason, "inactive");
});

test("maskEmail hides the address but keeps rows distinguishable", () => {
  assert.equal(maskEmail("john.doe@gmail.com"), "j•••@g•••.com");
  assert.equal(maskEmail("a@example.co.uk"), "a•••@e•••.uk");
  assert.equal(maskEmail("no-at-sign"), "•••");
  assert.equal(maskEmail(""), "•••");
  assert.equal(maskEmail(null), "•••");
  assert.ok(!maskEmail("john.doe@gmail.com").includes("gmail"));
  assert.ok(!maskEmail("john.doe@gmail.com").includes("john"));
});

test("payout policy: one constant, stated consistently", () => {
  assert.equal(PARTNER_PAYOUT_POLICY.minimumCents, 2500);
  assert.equal(partnerPayoutMinimumLabel(), "$25 USD");
  assert.equal(partnerPayoutMethodsList(), "PayPal, Wise, bank transfer or crypto");
  assert.equal(
    partnerPayoutPolicyShort(),
    "Sent by hand once a month to the method you choose in your partner dashboard, once your balance reaches $25 USD",
  );
  assert.equal(
    partnerPayoutPolicyFull(),
    "Sent by hand once a month to the method you choose in your partner dashboard (PayPal, Wise, bank transfer or crypto), once your balance reaches $25 USD. Smaller balances roll over to the next month.",
  );
});

