new='''/**
 * The owner's PAYOUT POLICY, as stated in the creator invite emails and the
 * partners' Terms PDF (2026-09-28): a MINIMUM PAYOUT THRESHOLD of $25 USD; once
 * a partner's balance reaches it, it is sent by hand once a month to their chosen
 * method; balances under the threshold roll over to the next month.
 *
 * STATED, NOT ENFORCED: payouts stay manual — an admin records each one as a
 * PartnerPayout on /admin/partners/<id>, and nothing here schedules, blocks or
 * sizes a payout. This is the ONE place the policy's numbers and wording live, so
 * the partner dashboard (components/nx/PartnerView.tsx Overview/Payouts/Terms) and
 * the invite email (lib/email-templates.ts creatorPartnerInvite) can't drift.
 * (Distinct from lib/affiliate.ts MIN_PAYOUT_CENTS — the peer "Refer & earn"
 * program's enforced cash-out floor.)
 */
export const MIN_PAYOUT_THRESHOLD_CENTS = 2500;
export const PARTNER_PAYOUT_CURRENCY = "USD";
export const PARTNER_PAYOUT_SCHEDULE = "once a month";

/** "$25" */
export function partnerPayoutThresholdShort(): string {
  const c = MIN_PAYOUT_THRESHOLD_CENTS;
  return `$${c % 100 === 0 ? c / 100 : (c / 100).toFixed(2)}`;
}

/** "$25 USD" */
export function partnerPayoutThresholdLabel(): string {
  return `${partnerPayoutThresholdShort()} ${PARTNER_PAYOUT_CURRENCY}`;
}

/** "PayPal, Wise, bank transfer or crypto" — from PAYOUT_METHODS, so a new method shows up here too. */
export function partnerPayoutMethodsList(): string {
  const names = PAYOUT_METHODS.map((m) => (m.key === "PAYPAL" || m.key === "WISE" ? m.label : m.label.toLowerCase()));
  return names.length > 1 ? `${names.slice(0, -1).join(", ")} or ${names[names.length - 1]}` : names.join("");
}

/** The owner's wording, verbatim — used on the Terms tab, the Payouts tab and in the invite email. */
export function partnerPayoutPolicyText(): string {
  return (
